"use client"

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react"
import { Check, Smartphone } from "lucide-react"
import { encode } from "uqr"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/hooks/use-controllable-state"
import {
  GridContainer,
  GridSection,
  GridColumns,
} from "@/components/ui/grid-layout/grid-layout"
import { SegmentedControl } from "@/components/ui/segmented-control/segmented-control"
import { resolveLabels, type Auth02Labels } from "./config"
import { CodeSignIn, PasswordSignIn, type SignInValues } from "./sign-in-form"
import { Auth02QrCode } from "./qr-code"

type Auth02Status = "pending" | "scanned" | "expired" | "confirmed" | "error"
type Auth02Provider = {
  id: string
  label: string
  icon?: ReactNode
  description?: string
}
type Auth02Code = { value: string; expiresAt?: number }
const DEFAULT_PROVIDERS: Auth02Provider[] = [
  { id: "app", label: "App 扫码", icon: <Smartphone aria-hidden /> },
]
const unavailable = async () => {
  throw new Error("请先接入认证服务")
}

/** 扫码优先登录；认证和服务端状态订阅由调用方负责。 */
function Auth02({
  brand = { name: "工作空间" },
  providers = DEFAULT_PROVIDERS,
  status: statusProp,
  defaultStatus = "pending",
  onStatusChange,
  onRequestCode,
  onConfirmed,
  onSignIn = unavailable,
  onSendCode = unavailable,
  labels,
  termsHref = "#",
  privacyHref = "#",
  className,
  ...props
}: Omit<ComponentProps<"div">, "onError"> & {
  /** 品牌名称与标志 */
  brand?: { name: string; logo?: ReactNode }
  /** 可配置扫码提供方，至少一项 */
  providers?: readonly Auth02Provider[]
  /** 受控扫码状态 */
  status?: Auth02Status
  /** 初始扫码状态 @default "pending" */
  defaultStatus?: Auth02Status
  onStatusChange?: (status: Auth02Status) => void
  /** 生成二维码；时间戳为毫秒，抛出的错误向用户展示 */
  onRequestCode: (providerId: string) => Promise<Auth02Code>
  /** 确认成功后的异步动作 */
  onConfirmed?: () => Promise<void>
  onSignIn?: (values: SignInValues) => Promise<void>
  onSendCode?: (phone: string) => Promise<void>
  labels?: Partial<Auth02Labels>
  termsHref?: string
  privacyHref?: string
}) {
  const text = resolveLabels(labels)
  const [status, setStatus] = useControllableState({
    prop: statusProp,
    defaultProp: defaultStatus,
    onChange: onStatusChange,
  })
  const [providerId, setProviderId] = useState(providers[0]?.id ?? "")
  const provider =
    providers.find((item) => item.id === providerId) ?? providers[0]
  const [view, setView] = useState<"qr" | "code" | "password">("qr")
  const [code, setCode] = useState<Auth02Code>()
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")
  const [seconds, setSeconds] = useState<number>()
  const sequence = useRef(0)
  const requestRef = useRef(onRequestCode)
  useEffect(() => {
    requestRef.current = onRequestCode
  }, [onRequestCode])
  const fallbackRef = useRef(text.requestFailed)
  useEffect(() => {
    fallbackRef.current = text.requestFailed
  }, [text.requestFailed])
  const request = useCallback(
    async (id: string, reset = true) => {
      const ticket = ++sequence.current
      setLoading(true)
      setError("")
      setCode(undefined)
      if (reset) setStatus("pending")
      try {
        const next = await requestRef.current(id)
        if (!next.value) throw new Error(fallbackRef.current)
        encode(next.value, { border: 4, ecc: "M" })
        if (ticket !== sequence.current) return
        setCode(next)
      } catch (caught) {
        if (ticket !== sequence.current) return
        setError(caught instanceof Error ? caught.message : fallbackRef.current)
        setStatus("error")
      } finally {
        if (ticket === sequence.current) setLoading(false)
      }
    },
    [setStatus],
  )
  const invalidate = useCallback(() => {
    sequence.current++
  }, [])
  const activeProviderId = provider?.id
  useEffect(() => {
    const timer = setTimeout(() => {
      if (activeProviderId) void request(activeProviderId, false)
    }, 0)
    return () => {
      clearTimeout(timer)
      // 清理时使正在等待的异步结果失效。
      invalidate()
    }
  }, [activeProviderId, request, invalidate]) // 提供方变化使旧请求失效
  useEffect(() => {
    if (!code?.expiresAt || !["pending", "scanned"].includes(status)) return
    const tick = () => {
      const remaining = Math.max(
        0,
        Math.ceil((code.expiresAt! - Date.now()) / 1000),
      )
      setSeconds(remaining)
      if (!remaining) setStatus("expired")
    }
    tick()
    const timer = setInterval(tick, 1000)
    return () => clearInterval(timer)
  }, [code, status, setStatus])
  const confirmedRef = useRef(onConfirmed)
  useEffect(() => {
    confirmedRef.current = onConfirmed
  }, [onConfirmed])
  useEffect(() => {
    if (status !== "confirmed") return
    let active = true
    Promise.resolve()
      .then(() => confirmedRef.current?.())
      .catch((caught) => {
        if (active) {
          setError(
            caught instanceof Error ? caught.message : fallbackRef.current,
          )
          setStatus("error")
        }
      })
    return () => {
      active = false
    }
  }, [status, setStatus])
  return (
    <div
      data-slot="auth-02"
      data-state={status}
      className={cn(
        "w-full overflow-x-clip bg-background py-8 text-foreground md:py-16",
        className,
      )}
      {...props}
    >
      <GridContainer className="max-w-4xl">
        <GridSection topLine className="space-y-3 px-4 py-6 sm:px-6">
          <div className="flex items-center gap-2 text-sm font-medium">
            {brand.logo}
            {brand.name}
          </div>
          <h1 className="text-2xl font-semibold tracking-tight">
            {text.title}
          </h1>
          <p className="text-sm leading-7 text-muted-foreground md:hidden">
            {text.mobileHint}
          </p>
          {/* 手机上通常扫不了自己屏幕上的码：短信入口提到最前面，桌面仍放在底部的备用入口里 */}
          {view === "qr" ? (
            <Button
              size="lg"
              className="w-full md:hidden"
              onClick={() => setView("code")}
            >
              {text.sms}
            </Button>
          ) : null}
        </GridSection>
        {view === "qr" ? (
          <GridSection>
            <GridColumns className="sm:grid-cols-1 sm:divide-x-0 sm:divide-y md:grid-cols-2 md:divide-x md:divide-y-0">
              <div className="flex flex-col items-center gap-4 px-4 py-8">
                <div
                  data-slot="auth-02-code-region"
                  aria-busy={loading}
                  className="relative flex size-64 max-w-full items-center justify-center"
                >
                  {loading ? (
                    <p role="status">{text.loading}</p>
                  ) : status === "scanned" || status === "confirmed" ? (
                    <div className="flex flex-col items-center gap-4 text-center">
                      {status === "confirmed" ? (
                        <Check aria-hidden className="size-12" />
                      ) : (
                        <Smartphone aria-hidden className="size-12" />
                      )}
                      <p>{text[status]}</p>
                    </div>
                  ) : status === "error" ? (
                    <p className="px-4 text-center text-destructive">
                      {error || text.error}
                    </p>
                  ) : code ? (
                    <Auth02QrCode value={code.value} label={text.qrLabel} />
                  ) : null}
                  {status === "expired" && !loading && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-background/95">
                      <p>{text.expired}</p>
                      <Button
                        size="lg"
                        onClick={() => provider && void request(provider.id)}
                      >
                        {text.refresh}
                      </Button>
                    </div>
                  )}
                </div>
                <p
                  aria-live="polite"
                  className="text-center text-sm text-muted-foreground"
                >
                  {loading
                    ? text.loading
                    : status === "error"
                      ? error || text.error
                      : text[status]}
                </p>
                {status === "pending" &&
                  seconds !== undefined &&
                  code?.expiresAt && (
                    <p className="font-mono text-xs text-muted-foreground">
                      {text.remaining.replace("{seconds}", String(seconds))}
                    </p>
                  )}
                {(status === "scanned" || status === "error") && (
                  <Button
                    size="lg"
                    variant="outline"
                    disabled={loading}
                    onClick={() => provider && void request(provider.id)}
                  >
                    {status === "error" ? text.retry : text.rescan}
                  </Button>
                )}
              </div>
              <div className="flex min-w-0 flex-col justify-center gap-6 px-4 py-8 sm:px-6">
                {providers.length > 1 && (
                  <SegmentedControl
                    aria-label={text.providerLabel}
                    size="lg"
                    value={provider?.id}
                    options={providers.map((item) => ({
                      value: item.id,
                      label: item.label,
                      icon: item.icon,
                    }))}
                    onValueChange={(id) => {
                      setProviderId(id)
                      setStatus("pending")
                    }}
                  />
                )}
                <div>
                  <h2 className="font-medium">{provider?.label}</h2>
                  <p className="mt-2 text-sm leading-7 text-muted-foreground">
                    {provider?.description}
                  </p>
                </div>
                <ol className="space-y-5">
                  {[text.stepOpen, text.stepScan, text.stepConfirm].map(
                    (step, i) => (
                      <li key={i} className="flex items-center gap-4">
                        <span className="flex size-8 shrink-0 items-center justify-center border border-edge font-mono text-sm">
                          {i + 1}
                        </span>
                        {step}
                      </li>
                    ),
                  )}
                </ol>
              </div>
            </GridColumns>
          </GridSection>
        ) : (
          <GridSection className="px-4 py-8">
            <div className="mx-auto max-w-md space-y-6">
              <h2 className="text-xl font-medium">
                {view === "code" ? text.sms : text.password}
              </h2>
              {view === "code" ? (
                <CodeSignIn
                  onSignIn={onSignIn}
                  onSendCode={onSendCode}
                  labels={labels}
                />
              ) : (
                <PasswordSignIn onSignIn={onSignIn} labels={labels} />
              )}
              <Button
                size="lg"
                variant="outline"
                className="w-full"
                onClick={() => setView("qr")}
              >
                {text.back}
              </Button>
            </div>
          </GridSection>
        )}
        <GridSection className="space-y-4 px-4 py-5 sm:px-6">
          <div className="flex flex-wrap gap-2">
            <Button
              size="lg"
              variant="outline"
              className={cn(view === "qr" && "max-md:hidden")}
              onClick={() => setView("code")}
            >
              {text.sms}
            </Button>
            <Button
              size="lg"
              variant="ghost"
              onClick={() => setView("password")}
            >
              {text.password}
            </Button>
          </div>
          <p className="text-xs leading-6 text-muted-foreground">
            {text.termsPrefix}{" "}
            <a className="underline" href={termsHref}>
              {text.termsOfService}
            </a>{" "}
            {text.termsConjunction}{" "}
            <a className="underline" href={privacyHref}>
              {text.privacyPolicy}
            </a>
          </p>
        </GridSection>
      </GridContainer>
    </div>
  )
}
export { Auth02 }
export type {
  Auth02Status,
  Auth02Provider,
  Auth02Code,
  Auth02Labels,
  SignInValues,
}

"use client"

import { useMemo } from "react"

import {
  PhoneInput,
  PhoneInputSendButton,
} from "@/components/ui/phone-input/phone-input"
import { ToggleSwitch } from "@/components/ui/toggle-switch/toggle-switch"

import { formatLabel, resolveLabels, type Auth02Labels } from "./config"
import { FormError, PasswordField, SubmitButton, TextField } from "./form-parts"
import {
  PHONE_LENGTH,
  createCodeSignInSchema,
  createSignInSchema,
} from "./schemas"
import { useAsyncAction, useAuthForm } from "./use-auth-form"

type SignInValues =
  | { method: "password"; account: string; password: string; remember: boolean }
  | { method: "code"; phone: string; code: string }

const CODE_COOLDOWN = 60

function PasswordSignIn({
  onSignIn,
  labels,
}: {
  onSignIn: (values: SignInValues) => Promise<void>
  labels?: Partial<Auth02Labels>
}) {
  // labels 引用不变时 text 与 schema 都不重建，避免每次输入都重新编译 zod schema
  const text = useMemo(() => resolveLabels(labels), [labels])
  const schema = useMemo(() => createSignInSchema(text), [text])
  const form = useAuthForm(
    schema,
    { account: "", password: "", remember: false },
    { fallbackError: text.requestFailed },
  )
  return (
    <form
      data-slot="auth-02-sign-in-password"
      noValidate
      onSubmit={form.handleSubmit((values) =>
        onSignIn({ method: "password", ...values }),
      )}
      className="flex flex-col gap-5"
    >
      <FormError message={form.formError} />
      <TextField
        id="sign-in-account"
        label={text.accountLabel}
        autoComplete="username"
        placeholder={text.accountPlaceholder}
        value={form.values.account}
        error={form.errors.account}
        onChange={(event) => form.setValue("account", event.target.value)}
        onBlur={() => form.blur("account")}
      />
      <PasswordField
        id="sign-in-password"
        label={text.passwordLabel}
        autoComplete="current-password"
        placeholder={text.passwordPlaceholder}
        value={form.values.password}
        error={form.errors.password}
        onChange={(event) => form.setValue("password", event.target.value)}
        onBlur={() => form.blur("password")}
        labels={labels}
      />
      {/* 记住登录状态是即时生效的开关，不是需要同意的声明，所以用开关而不是复选框 */}
      <ToggleSwitch
        label={text.remember}
        tone="primary"
        checked={form.values.remember}
        onCheckedChange={(checked) => form.setValue("remember", checked)}
      />
      <SubmitButton pending={form.pending} pendingText={text.signInPending}>
        {text.signInSubmit}
      </SubmitButton>
    </form>
  )
}

function CodeSignIn({
  onSignIn,
  onSendCode,
  labels,
}: {
  onSignIn: (values: SignInValues) => Promise<void>
  onSendCode: (phone: string) => Promise<void>
  labels?: Partial<Auth02Labels>
}) {
  const text = useMemo(() => resolveLabels(labels), [labels])
  const schema = useMemo(() => createCodeSignInSchema(text), [text])
  const form = useAuthForm(
    schema,
    { phone: "", code: "" },
    { fallbackError: text.requestFailed },
  )
  const sender = useAsyncAction(text.requestFailed)

  // 失败时必须 throw：PhoneInputSendButton 遇到抛错就不进入倒计时，用户可以马上重试
  const sendCode = async () => {
    if (!form.validateField("phone"))
      throw new Error(text.validationPhoneInvalid)
    const sent = await sender.run(() => onSendCode(form.values.phone))
    if (!sent) throw new Error(text.requestFailed)
  }
  const phoneInvalid = formatLabel(text.validationPhoneInvalid, {
    length: PHONE_LENGTH,
  })
  return (
    <form
      data-slot="auth-02-sign-in-code"
      noValidate
      onSubmit={form.handleSubmit((values) =>
        onSignIn({ method: "code", ...values }),
      )}
      className="flex flex-col gap-5"
    >
      <FormError message={form.formError ?? sender.error} />
      <PhoneInput
        id="sign-in-phone"
        size="lg"
        label={text.phoneLabel}
        placeholder={text.phonePlaceholder}
        value={form.values.phone}
        error={form.errors.phone}
        labels={{ invalid: phoneInvalid, required: phoneInvalid }}
        onValueChange={(phone) => form.setValue("phone", phone)}
        onBlur={() => form.blur("phone")}
        action={
          <PhoneInputSendButton
            cooldown={CODE_COOLDOWN}
            onSend={sendCode}
            labels={{
              send: text.sendCode,
              sending: text.sendCodePending,
              countdown: text.resendCode,
              resend: text.sendCode,
            }}
          />
        }
      />
      <TextField
        id="sign-in-code"
        label={text.codeLabel}
        inputMode="numeric"
        maxLength={6}
        autoComplete="one-time-code"
        placeholder={text.codePlaceholder}
        value={form.values.code}
        error={form.errors.code}
        onChange={(event) => form.setValue("code", event.target.value)}
        onBlur={() => form.blur("code")}
      />
      <SubmitButton pending={form.pending} pendingText={text.signInPending}>
        {text.signInSubmit}
      </SubmitButton>
    </form>
  )
}

export { PasswordSignIn, CodeSignIn }
export type { SignInValues }

import { encode } from "uqr"

/** 保留四模块静区，SVG 只使用主题色。 */
function Auth02QrCode({ value, label }: { value: string; label: string }) {
  const qr = encode(value, { border: 4, ecc: "M" })
  return (
    <svg
      data-slot="auth-02-qr-code"
      role="img"
      aria-label={label}
      viewBox={`0 0 ${qr.size} ${qr.size}`}
      className="size-60 max-w-full"
      shapeRendering="crispEdges"
    >
      <rect width={qr.size} height={qr.size} className="fill-background dark:fill-foreground" />
      <path
        className="fill-foreground dark:fill-background"
        d={qr.data
          .flatMap((row, y) =>
            row.flatMap((cell, x) => (cell ? [`M${x},${y}h1v1h-1z`] : [])),
          )
          .join("")}
      />
    </svg>
  )
}
export { Auth02QrCode }

"use client"

import { Auth02 } from "@/components/auth-02/auth-02"

/** 将生成二维码的回调换成认证服务；不要在客户端创建认证凭据。 */
export default function LoginPage() {
  return (
    <Auth02
      onRequestCode={async () => {
        throw new Error("请接入生成登录二维码的接口")
      }}
    />
  )
}

import { z } from "zod"

import { formatLabel, type Auth02Labels } from "./config"

/**
 * 校验规则常量：改策略只改这里，提示文案里的 {min}、{length} 会自动带入新值。
 * 提示文案本身全部来自 labels（config.ts 的 validation* 键），可逐实例覆盖。
 */

/** 密码最少位数 */
const PASSWORD_MIN_LENGTH = 8

/** 姓名最少字符数 */
const NAME_MIN_LENGTH = 2

/** 短信验证码位数 */
const CODE_LENGTH = 6

/** 中国大陆手机号位数，需与 PHONE_PATTERN 的位数一致 */
const PHONE_LENGTH = 11

/** 中国大陆 11 位手机号；面向海外用户时替换这条规则 */
const PHONE_PATTERN = /^1[3-9]\d{9}$/

/** 验证码只接受数字，位数由 CODE_LENGTH 决定 */
const CODE_PATTERN = new RegExp(`^\\d{${CODE_LENGTH}}$`)

function emailField(labels: Auth02Labels) {
  return z
    .string()
    .trim()
    .min(1, labels.validationEmailRequired)
    .email(labels.validationEmailInvalid)
}

function passwordField(labels: Auth02Labels) {
  return z
    .string()
    .min(
      PASSWORD_MIN_LENGTH,
      formatLabel(labels.validationPasswordMin, { min: PASSWORD_MIN_LENGTH }),
    )
    .regex(/[A-Za-z]/, labels.validationPasswordLetter)
    .regex(/\d/, labels.validationPasswordDigit)
}

function phoneField(labels: Auth02Labels) {
  return z
    .string()
    .trim()
    .regex(
      PHONE_PATTERN,
      formatLabel(labels.validationPhoneInvalid, { length: PHONE_LENGTH }),
    )
}

/** 密码登录。labels 需是合并过默认值的完整文案。 */
function createSignInSchema(labels: Auth02Labels) {
  return z.object({
    account: z.string().trim().min(1, labels.validationAccountRequired),
    password: z.string().min(1, labels.validationPasswordRequired),
    remember: z.boolean(),
  })
}

/** 验证码登录。 */
function createCodeSignInSchema(labels: Auth02Labels) {
  return z.object({
    phone: phoneField(labels),
    code: z
      .string()
      .trim()
      .regex(
        CODE_PATTERN,
        formatLabel(labels.validationCodeInvalid, { length: CODE_LENGTH }),
      ),
  })
}

/** 注册：确认密码与条款勾选也在前端校验。 */
function createSignUpSchema(labels: Auth02Labels) {
  return z
    .object({
      name: z
        .string()
        .trim()
        .min(
          NAME_MIN_LENGTH,
          formatLabel(labels.validationNameMin, { min: NAME_MIN_LENGTH }),
        ),
      email: emailField(labels),
      password: passwordField(labels),
      confirm: z.string().min(1, labels.validationConfirmRequired),
      terms: z
        .boolean()
        .refine((value) => value, labels.validationTermsRequired),
    })
    .refine((values) => values.password === values.confirm, {
      message: labels.validationPasswordMismatch,
      path: ["confirm"],
    })
}

/** 找回密码。 */
function createForgotPasswordSchema(labels: Auth02Labels) {
  return z.object({ email: emailField(labels) })
}

export {
  CODE_LENGTH,
  NAME_MIN_LENGTH,
  PASSWORD_MIN_LENGTH,
  PHONE_LENGTH,
  PHONE_PATTERN,
  createCodeSignInSchema,
  createForgotPasswordSchema,
  createSignInSchema,
  createSignUpSchema,
}

"use client"

import { useCallback, useState, type FormEvent } from "react"
import type { z } from "zod"

import { DEFAULT_LABELS } from "./config"

type FieldErrors = Record<string, string>
// 字面量初始值（false、""）会被推断成字面量类型，这里放宽为 boolean / string
type Widen<T> = {
  [K in keyof T]: T[K] extends boolean
    ? boolean
    : T[K] extends string
      ? string
      : T[K]
}

/** 每个字段只保留第一条错误，避免一次堆出一长串提示 */
function toErrors(error: z.ZodError): FieldErrors {
  const errors: FieldErrors = {}
  for (const issue of error.issues) {
    const key = String(issue.path[0] ?? "")
    if (key && !(key in errors)) errors[key] = issue.message
  }
  return errors
}

/** 把未知错误转成可展示的中文文案；没有 message 时用传入的兜底文案。 */
function errorMessage(
  error: unknown,
  fallback: string = DEFAULT_LABELS.requestFailed,
) {
  return error instanceof Error && error.message ? error.message : fallback
}

/** 包装一个异步动作：管理 loading，并把抛出的错误转成可展示的中文文案。 */
function useAsyncAction(fallbackError: string = DEFAULT_LABELS.requestFailed) {
  const [pending, setPending] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const run = useCallback(
    async (action: () => Promise<void>) => {
      setPending(true)
      setError(null)
      try {
        await action()
        return true
      } catch (caught) {
        setError(errorMessage(caught, fallbackError))
        return false
      } finally {
        setPending(false)
      }
    },
    [fallbackError],
  )
  return { pending, error, run, clearError: () => setError(null) }
}

/**
 * 极简受控表单：zod 校验 + 字段错误 + 提交状态。
 * 首次提交前，字段失焦时校验该字段；提交失败后，输入时实时重新校验。
 */
function useAuthForm<I extends Record<string, string | boolean>>(
  schema: z.ZodType,
  initial: I,
  options: { fallbackError?: string } = {},
) {
  type V = Widen<I>
  const [values, setValues] = useState<V>(initial as V)
  const [errors, setErrors] = useState<FieldErrors>({})
  const [submitted, setSubmitted] = useState(false)
  const action = useAsyncAction(options.fallbackError)

  const check = useCallback(
    (next: V) => {
      const result = schema.safeParse(next)
      return result.success ? {} : toErrors(result.error)
    },
    [schema],
  )

  const setValue = <K extends keyof V & string>(key: K, value: V[K]) => {
    const next = { ...values, [key]: value }
    setValues(next)
    if (submitted) setErrors(check(next))
    else if (errors[key]) setErrors((prev) => ({ ...prev, [key]: "" }))
  }
  const blur = (key: keyof V & string) => {
    if (values[key] === "" && !submitted) return
    const found = check(values)[key] ?? ""
    setErrors((prev) => ({ ...prev, [key]: found }))
  }
  const handleSubmit =
    (onValid: (values: V) => Promise<void>) =>
    async (event: FormEvent<HTMLFormElement>) => {
      event.preventDefault()
      setSubmitted(true)
      const found = check(values)
      setErrors(found)
      if (Object.keys(found).length) return
      await action.run(() => onValid(values))
    }

  return {
    values,
    errors,
    setValue,
    blur,
    handleSubmit,
    pending: action.pending,
    formError: action.error,
    run: action.run,
    /** 校验单个字段并返回是否通过（用于「发送验证码」前校验手机号） */
    validateField: (key: keyof V & string) => {
      const found = check(values)[key] ?? ""
      setSubmitted(true)
      setErrors((prev) => ({ ...prev, [key]: found }))
      return !found
    },
  }
}

export { errorMessage, useAsyncAction, useAuthForm }
export type { FieldErrors }

"use client"

import { Eye, EyeOff, Loader2 } from "lucide-react"
import { useState, type ComponentProps, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { BarField } from "@/components/ui/bar-field/bar-field"
import { cn } from "@/lib/utils"

import { resolveLabels, type Auth02Labels } from "./config"

/**
 * 方条输入框：标签在条内左侧，值靠右；错误文字在条下方，通过 aria-describedby 关联，读屏会一并读出。
 * 高度取 lg 档（36px，触屏 44px），与区块里 size="lg" 的按钮等高。
 */
function TextField({
  id,
  label,
  error,
  footerAction,
  trailing,
  className,
  value,
  defaultValue,
  ...props
}: Omit<ComponentProps<"input">, "id" | "size"> & {
  id: string
  label: string
  error?: string
  /** 条下方右侧的操作，例如「忘记密码？」；有错误文字时错误在左、操作在右 */
  footerAction?: ReactNode
  /** 条内最右侧的元素，例如显示/隐藏密码按钮 */
  trailing?: ReactNode
}) {
  return (
    <BarField
      {...props}
      value={value === undefined ? undefined : String(value)}
      defaultValue={
        defaultValue === undefined ? undefined : String(defaultValue)
      }
      id={id}
      label={label}
      error={error}
      footerAction={footerAction}
      suffix={trailing}
      size="lg"
      className={cn(className)}
    />
  )
}

/** 带显示/隐藏切换的密码框。 */
function PasswordField({
  labels,
  ...props
}: Omit<ComponentProps<typeof TextField>, "type" | "trailing"> & {
  labels?: Partial<Auth02Labels>
}) {
  const text = resolveLabels(labels)
  const [visible, setVisible] = useState(false)
  return (
    <TextField
      {...props}
      type={visible ? "text" : "password"}
      trailing={
        <Button
          type="button"
          variant="ghost"
          size="icon-lg"
          onClick={() => setVisible((value) => !value)}
          aria-label={visible ? text.hidePassword : text.showPassword}
          aria-pressed={visible}
          // 按钮比条内边距大，向右让出 8px，图标视觉上仍与条的右缘留足间距
          className="shrink-0 text-muted-foreground hover:text-foreground"
        >
          {visible ? <EyeOff aria-hidden="true" /> : <Eye aria-hidden="true" />}
        </Button>
      }
    />
  )
}

/** 表单级错误（接口返回的失败原因等），出现时读屏会立即朗读。 */
function FormError({ message }: { message: string | null }) {
  if (!message) return null
  return (
    <p
      data-slot="auth-02-form-error"
      role="alert"
      className="rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive"
    >
      {message}
    </p>
  )
}

/** 提交按钮：pending 时显示转圈并禁用。 */
function SubmitButton({
  pending,
  pendingText,
  children,
}: {
  pending: boolean
  pendingText: string
  children: ReactNode
}) {
  return (
    <Button
      data-slot="auth-02-submit-button"
      type="submit"
      size="lg"
      className="w-full"
      disabled={pending}
    >
      {pending ? (
        <>
          <Loader2 aria-hidden="true" className="animate-spin" />
          {pendingText}
        </>
      ) : (
        children
      )}
    </Button>
  )
}

/** 视图头部：标题 + 说明。每个视图只有一个 h1。 */
function ViewHeading({
  title,
  description,
}: {
  title: string
  description: string
}) {
  return (
    <div data-slot="auth-02-view-heading" className="flex flex-col gap-1">
      <h1 className="text-2xl font-bold tracking-tight">{title}</h1>
      <p className="text-sm text-muted-foreground">{description}</p>
    </div>
  )
}

/** 文字链接样式的按钮，用于视图切换。 */
function LinkButton({ className, ...props }: ComponentProps<"button">) {
  return (
    <button
      data-slot="auth-02-link-button"
      type="button"
      className={cn(
        "rounded-sm font-medium text-primary underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        className,
      )}
      {...props}
    />
  )
}

export {
  FormError,
  LinkButton,
  PasswordField,
  SubmitButton,
  TextField,
  ViewHeading,
}

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }
